//! «Lisenser» — the third-party notices the installers ship (OMBYGGING A1b).
//!
//! MIT and Apache-2.0 require the notices to travel with what we distribute,
//! and ffmpeg is GPL: whoever holds an installer is entitled to know that and
//! where the source lives. `THIRD-PARTY-NOTICES.html` is generated by
//! `npm run licenses:notices` (cargo-about + the npm runtime deps), checked in
//! under `src-tauri/resources/`, and bundled as a Tauri resource
//! (`bundle.resources` in `tauri.conf.json`).
//!
//! ## Path policy
//!
//! No path in, no path out: the command reads exactly one file, whose name is a
//! constant, from the app's own resource directory. The renderer gets the
//! file's TEXT and shows it in a sandboxed frame, so there is nothing for a
//! compromised webview to point elsewhere (same stance as `commands::logs`, so
//! it needs no entry in `path_ratchet`).
//!
//! Featureless: a licence page that exists in some builds only is not a notice.

use std::path::PathBuf;

use crate::error::{AppError, AppResult};

/// The bundled file's path relative to the resource directory — the same string
/// `tauri.conf.json` lists under `bundle.resources`.
pub const NOTICES_RESOURCE: &str = "resources/THIRD-PARTY-NOTICES.html";

/// Where to look for the notices, best first.
///
/// 1. The resource directory — the only place that exists in an installed app.
/// 2. The source tree, debug builds only: under `tauri dev` the resource dir is
///    not guaranteed to be populated, and a licence page that is blank in dev
///    would hide exactly the bug this command exists to prevent in release.
fn candidates(resource_dir: Option<PathBuf>) -> Vec<PathBuf> {
    let mut out = Vec::new();
    if let Some(dir) = resource_dir {
        out.push(dir.join(NOTICES_RESOURCE));
    }
    if cfg!(debug_assertions) {
        out.push(PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(NOTICES_RESOURCE));
    }
    out
}

/// The first candidate that reads, or an English diagnostic naming all the
/// places tried (a developer message — see `commands::logs` on why English).
fn read_first(paths: &[PathBuf]) -> AppResult<String> {
    for p in paths {
        if let Ok(text) = std::fs::read_to_string(p) {
            return Ok(text);
        }
    }
    Err(AppError::Internal(format!(
        "third-party notices not found (tried {} location(s))",
        paths.len()
    )))
}

/// The text of `THIRD-PARTY-NOTICES.html`.
#[tauri::command]
pub async fn licenses_notices(app: tauri::AppHandle) -> AppResult<String> {
    use tauri::Manager;
    let dir = app.path().resource_dir().ok();
    read_first(&candidates(dir))
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The file the installers ship must exist in the tree and say the two
    /// things the licences require: that ffmpeg is GPL, and where its source
    /// is. A stub file that merely exists would pass `tauri build`.
    #[test]
    fn the_checked_in_notices_name_ffmpeg_gpl_and_its_source() {
        let p = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(NOTICES_RESOURCE);
        let text = read_first(&[p]).expect("notices file is checked in");
        assert!(text.contains("FFmpeg (GPL)"));
        assert!(text.contains("https://ffmpeg.org/download.html"));
        assert!(text.contains("github.com/SundaySuite-app/sundayrec"));
        assert!(text.contains("MIT License") || text.contains("Permission is hereby granted"));
    }

    /// The path in this module and the one the bundler is told to copy are the
    /// same string — otherwise the file is bundled under one name and looked
    /// up under another, and the page is empty only in an installed app.
    #[test]
    fn the_resource_path_is_the_one_tauri_conf_bundles() {
        let conf = include_str!("../../tauri.conf.json");
        assert!(conf.contains(&format!("\"{NOTICES_RESOURCE}\"")));
    }

    #[test]
    fn a_missing_file_is_an_error_not_an_empty_page() {
        let r = read_first(&[PathBuf::from("/nonexistent/notices.html")]);
        assert!(r.is_err());
    }

    #[test]
    fn the_resource_dir_is_tried_before_the_source_tree() {
        let c = candidates(Some(PathBuf::from("/res")));
        assert_eq!(c[0], PathBuf::from("/res").join(NOTICES_RESOURCE));
    }
}
